'use strict';
// One require() of each accessor-exporting package; what it answered, by
// kind and content.
function show(value) {
	if (value === null) return 'null';
	if (value === undefined) return 'undefined';
	if (typeof value === 'function') return 'function answering ' + value();
	if (typeof value === 'object') return 'object of read ' + value.reads;
	if (typeof value === 'string') return 'string "' + value + '"';
	if (typeof value === 'number') return 'number ' + value;
	return 'another kind';
}

const fromObject = require('palette-object');
const fromZero = require('palette-zero');
const fromFirstZero = require('palette-first-zero');
const fromSecondUndefined = require('palette-second-undefined');
const fromFirstTwoNull = require('palette-first-two-null');
const fromText = require('palette-text');
const fromEmptyText = require('palette-empty-text');
const fromFunction = require('palette-function');
const fromFifthZero = require('palette-fifth-zero');

exports.report = function report() {
	return [
		'object: ' + show(fromObject),
		'zero: ' + show(fromZero),
		'first-zero: ' + show(fromFirstZero),
		'second-undefined: ' + show(fromSecondUndefined),
		'first-two-null: ' + show(fromFirstTwoNull),
		'text: ' + show(fromText),
		'empty-text: ' + show(fromEmptyText),
		'function: ' + show(fromFunction),
		'fifth-zero: ' + show(fromFifthZero),
	];
};
